export function isVocabLevel(id: string): id is IibsVocabLevel {
  return id === "A" || id === "B" || id === "C" || id === "D" || id === "E"
}

export function vocabLessons(id: string): IibsVocabWord[][] | null {
  return isVocabLevel(id) ? IIBS_VOCAB[id] : null
}
